class RegisteredGuide extends Guest
{
    String roomtype;
    RegisteredGuide(String guestname, String roomtype)
    {
        super(guestname);
        this.roomtype = roomtype;
    }

    void display()
    {
        super.display();
        System.out.println("Room Type: "+roomtype);
    }
}

class LoyaltyGuest extends RegisteredGuide
{
    int num;
    double ldp;
    double gross, dis, tot;
    LoyaltyGuest(String guestname, String roomtype, int num, double ldp)
    {
        super(guestname, roomtype);
        this.num=num;
        this.ldp=ldp;
    }

    void calculate()
    {
        if(roomtype.equals("Standard"))
            gross = 1000*num;
        else if(roomtype.equals("Deluxe"))
            gross = 2000*num;
        else
            gross = 3500*num;

        dis = gross*ldp/100.0;
        tot = gross - dis;
    }

    void display()
    {
        super.display();
        calculate();
        System.out.println("Total Bill: "+tot);
    }
}

