import java.util.HashSet;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        
        ArrayList<String> registered = new ArrayList<>();
        LinkedList<String> verification = new LinkedList<>();

        String input = scanner.nextLine();
        
        String[] names = input.split(",");
        for (String name : names) {
            String trimmedName = name.trim();
            if (!trimmedName.isEmpty()) {
                registered.add(trimmedName);
                verification.add(trimmedName);
            }
        }

        HashSet<String> uniqueStudents = new HashSet<>(registered);

        System.out.println(registered.size() + " registered; " + uniqueStudents.size() + " unique");

        scanner.close();
    }
}

