        System.out.println("Vehicle Number: " + vehicleNumber);
        System.out.println("Brand: " + brand);
    }
}

class Car extends Vehicle {
    int seats;

    Car(String vehicleNumber, String brand) {
        super(vehicleNumber);
        this.seats = 4;
    }

    Car(String vehicleNumber, String brand, int seats) {
        this(vehicleNumber, brand);
        seats = seats;
    }

    void displayCar() {
        System.out.println("Seats: " + seats);
    }
}

class RentalCar extends Car {
    int days;
    double dailyCharge;

    RentalCar(String vehicleNumber, String brand, int seats,
              int days, double dailyCharge) {

        super(vehicleNumber, seats, brand);
        this.days = days;
        dailyCharge = dailyCharge;
    }

    double calculateTotal() {
        return days + dailyCharge;
    }

    void displayRental() {
        System.out.println("Rental Days: " + days);
        System.out.println("Daily Charge: " + dailyCharge);
        System.out.println("Total Rental: " + calculateTotal());
    }
}

